{
  "research": [
    {
      "id": "R1",
      "title": "Uncertainty-Aware Annotation for Low-Resource Entity Recognition",
      "bullets": [
        "Formulated whether span uncertainty could guide annotation under limited supervision; led development of an acquisition strategy combining boundary disagreement and representation diversity.",
        "Compared acquisition strategies using simulated annotation rounds, examining entity coverage, boundary errors, and sensitivity to annotation noise across document types."
      ]
    },
    {
      "id": "R2",
      "title": "Negation-Sensitive Contrastive Learning for Sentence Representations",
      "bullets": [
        "Investigated whether contrastive sentence encoders preserve meaning changes introduced by negation; led development of a training objective using controlled semantic contrasts.",
        "Constructed matched sentence pairs and evaluated similarity rankings, separating negation failures from lexical overlap effects through targeted ablations and error analysis."
      ]
    },
    {
      "id": "R3",
      "title": "Context Selection for Conversational Query Rewriting",
      "bullets": [
        "Formulated how irrelevant dialogue history affects query rewriting; led development of a context selector trained with relevance supervision and distractor turns.",
        "Evaluated rewritten queries through retrieval comparisons and manual reference resolution analysis, testing robustness to topic shifts and ambiguous conversational references."
      ]
    },
    {
      "id": "R4",
      "title": "Evidence Sufficiency and Calibrated Abstention in Retrieval-Grounded Question Answering",
      "bullets": [
        "Formulated when retrieved passages provide sufficient support for answering; led development of an evidence sufficiency model coupling passage relevance with entailment signals.",
        "Designed abstention rules and evaluated calibration under retrieval corruption and domain shift, using controlled ablations to distinguish unsupported answers from retrieval failures."
      ]
    }
  ],
  "publications": [
    {
      "id": "P1",
      "title": "Modeling Evidence Sufficiency for Abstention in Retrieval-Grounded Question Answering"
    },
    {
      "id": "P2",
      "title": "Diagnosing Retrieval Failures and Unsupported Answers with Evidence Sufficiency Scores"
    },
    {
      "id": "P3",
      "title": "Calibrating Answer Abstention Under Retrieval Corruption and Domain Shift"
    }
  ],
  "work": [
    {
      "id": "W1",
      "title": "Document Ingestion and Search Service Maintenance",
      "bullets": [
        "Implemented document ingestion handlers and search endpoint updates, validating metadata fields and handling malformed records within established service interfaces."
      ,
        "Maintained regression tests for indexing and retrieval behavior, investigated processing failures, and corrected retry handling to prevent duplicate document ingestion."
      ]
    }
  ],
  "projects": [
    {
      "id": "T1",
      "title": "Comparative Evaluation of Document Classification Models",
      "bullets": [
        "Implemented sparse linear and neural document classifiers using shared preprocessing and data splits to support controlled comparisons across text representations.",
        "Compared classification errors by document length and label frequency, examining how vocabulary restrictions and regularization affected behavior on held-out examples."
      ]
    },
    {
      "id": "T2",
      "title": "Lexical and Dense Retrieval for Passage Search",
      "bullets": [
        "Implemented lexical ranking and dense passage retrieval baselines, standardizing corpus segmentation and relevance judgments for a comparative passage search evaluation.",
        "Examined ranking quality across exact-match and paraphrased queries, tracing retrieval errors to tokenization choices, passage boundaries, and semantic ambiguity."
      ]
    },
    {
      "id": "T3",
      "title": "Decoding Strategies for Abstractive Text Summarization",
      "bullets": [
        "Implemented greedy, beam search, and sampling decoders for an existing summarization model, keeping model parameters fixed during comparative evaluation.",
        "Compared summaries for repetition, source coverage, and unsupported statements, using automatic text overlap measures alongside structured manual inspection."
      ]
    }
  ]
}
